<?php namespace App\Exports; use Maatwebsite\Excel\Concerns\Exportable; use Maatwebsite\Excel\Concerns\WithMultipleSheets; use App\Models\Sede; use App\Models\Area; use App\Models\Cargo; use App\Models\Venta; use App\Models\Tarea; use App\Models\SoporteTicket; use App\Models\Caja; class MasterTemplateExport implements WithMultipleSheets { use Exportable; protected $empresaId; protected $isTemplate; public function __construct($empresaId = null, $isTemplate = false) { $this->empresaId = $empresaId; $this->isTemplate = $isTemplate; } public function sheets(): array { $sheets = [ new ClientesExportSheet($this->empresaId, $this->isTemplate), new ProveedoresExportSheet($this->empresaId, $this->isTemplate), new ProductosExportSheet($this->empresaId, $this->isTemplate), new ServiciosExportSheet($this->empresaId, $this->isTemplate), new EmpleadosExportSheet($this->empresaId, $this->isTemplate), ]; if (!$this->isTemplate && $this->empresaId) { $empresaId = $this->empresaId; $sheets[] = new GenericExportSheet("Sedes", ["ID", "Nombre", "Direccion", "Telefono", "Estado", "Creado En"], function() use ($empresaId) { return Sede::where("empresa_id", $empresaId)->get(); }, function($sede) { return [$sede->id, $sede->nombre, $sede->direccion, $sede->telefono, $sede->estado, $sede->created_at]; }); $sheets[] = new GenericExportSheet("Areas", ["ID", "Nombre", "Descripcion", "Activo", "Creado En"], function() use ($empresaId) { return Area::where("empresa_id", $empresaId)->get(); }, function($area) { return [$area->id, $area->nombre, $area->descripcion, $area->activo ? "Si" : "No", $area->created_at]; }); $sheets[] = new GenericExportSheet("Cargos", ["ID", "Area ID", "Rol ID", "Nombre", "Descripcion", "Activo", "Creado En"], function() use ($empresaId) { return Cargo::where("empresa_id", $empresaId)->get(); }, function($cargo) { return [$cargo->id, $cargo->area_id, $cargo->rol_id, $cargo->nombre, $cargo->descripcion, $cargo->activo ? "Si" : "No", $cargo->created_at]; }); $sheets[] = new GenericExportSheet("Ventas", ["ID", "Factura", "Cliente ID", "Subtotal", "Impuestos", "Descuentos", "Total", "Metodo Pago", "Estado", "Vendedor ID", "Creado En"], function() use ($empresaId) { return Venta::where("empresa_id", $empresaId)->get(); }, function($venta) { return [$venta->id, $venta->factura_consecutivo, $venta->cliente_id, $venta->subtotal, $venta->impuestos, $venta->descuentos, $venta->total, $venta->metodo_pago, $venta->estado, $venta->vendedor_id, $venta->created_at]; }); $sheets[] = new GenericExportSheet("Tareas", ["ID", "Area ID", "Titulo", "Descripcion", "Asignador ID", "Asignado ID", "Tipo", "Estado", "Creado En"], function() use ($empresaId) { return Tarea::where("empresa_id", $empresaId)->get(); }, function($tarea) { return [$tarea->id, $tarea->area_id, $tarea->titulo, $tarea->descripcion, $tarea->asignador_id, $tarea->asignado_id, $tarea->tipo, $tarea->estado, $tarea->created_at]; }); $sheets[] = new GenericExportSheet("Soporte", ["ID", "Usuario ID", "Asunto", "Mensaje", "Estado", "Tecnico ID", "Notas Resolucion", "Creado En"], function() use ($empresaId) { return SoporteTicket::where("empresa_id", $empresaId)->get(); }, function($ticket) { return [$ticket->id, $ticket->usuario_id, $ticket->asunto, $ticket->mensaje, $ticket->estado, $ticket->tecnico_id, $ticket->notas_resolucion, $ticket->created_at]; }); $sheets[] = new GenericExportSheet("Cajas", ["ID", "Usuario Apertura", "Usuario Cierre", "Saldo Inicial", "Saldo Final", "Abierta En", "Cerrada En", "Estado"], function() use ($empresaId) { return Caja::where("empresa_id", $empresaId)->get(); }, function($caja) { return [$caja->id, $caja->usuario_apertura, $caja->usuario_cierre, $caja->saldo_inicial, $caja->saldo_final, $caja->abierta_en, $caja->cerrada_en, $caja->estado]; }); } return $sheets; } }
